// PV6 upload links, over the real router, index core, pipeline, policy engine and SQLite D1. Guests reach the
// internal routes as serve-worker does (no actor). Fixtures are generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { route } from "@media-worker/router";
import { FakeDigestStream, World, type User } from "./harness.js";
import { jpegWithGps } from "./fixtures.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

describe("upload links", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User;
  let base: string;

  beforeEach(async () => {
    w = new World();
    w.now = new Date();
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Inbox" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "POST", `${base}/folders`, { path: "/incoming" });
  });

  const create = (body: Record<string, unknown>, user = owner) => w.call(user, "POST", `${base}/upload-links`, { folder: "/incoming", ...body });
  const token = (url: string) => url.split("/_u/")[1]!;
  const open = (t: string) => w.call(null, "POST", "/v1/media/upload-links/open", { token: t });
  /** A guest file, as serve-worker sends it (node's Request drops Content-Length, so a plain request object). */
  async function send(t: string, name: string, bytes: Uint8Array, mime = "application/octet-stream") {
    const qs = new URLSearchParams({ token: t, name, mime });
    const req = {
      url: `https://media.internal/v1/media/upload-links/upload?${qs}`,
      method: "POST",
      headers: new Headers({ "content-type": "application/octet-stream", "content-length": String(bytes.length), "x-request-id": "req_test" }),
      arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength),
    } as unknown as Request;
    const res = await route(req, w.env, { now: () => w.now });
    const text = await res.text();
    return { status: res.status, json: text ? JSON.parse(text) : null };
  }
  const files = async (q = "") => (await w.call(owner, "GET", `${base}/files${q}`)).json.data.files;

  it("a guest's file lands private in the link's folder, goes through the pipeline, and waits for review", async () => {
    const r = await create({ label: "Press kit" });
    expect(r.status).toBe(201);
    expect(r.json.data.url).toMatch(/\/_u\/[A-Za-z0-9_-]{43}$/);
    expect(r.json.data.uploadLink).toMatchObject({ folder: "/incoming", label: "Press kit", requiresReview: true, uploads: 0, status: "active" });
    const t = token(r.json.data.url);
    expect(JSON.stringify(w.db.prepare(`SELECT * FROM media_upload_links`).all())).not.toContain(t);

    const info = await open(t);
    expect(info.json.data).toMatchObject({ label: "Press kit", remaining: { files: 20 }, reviewed: true });

    const img = jpegWithGps();
    const sent = await send(t, "photo.jpg", img, "image/jpeg");
    expect(sent.status).toBe(201);
    expect(sent.json.data.file).toMatchObject({ name: "photo.jpg", status: "processing", reviewed: true });
    expect(w.workflows.at(-1)!.params.requireSafety).toBe(true);
    await w.runPipelines();

    const queued = await files("?review=1");
    expect(queued).toHaveLength(1);
    expect(queued[0]).toMatchObject({ name: "photo.jpg", folder: "/incoming", status: "held", visibility: "private", pipelineNote: "review:upload_link" });
    expect(queued[0].uploadedBy).toMatch(/^upl_[0-9a-f]{32}$/);

    const ok = await w.call(editor, "POST", `${base}/files/${queued[0].id}/review`, { decision: "approve" });
    expect(ok.json.data.file).toMatchObject({ status: "private", visibility: "private" });
    expect(await files("?review=1")).toHaveLength(0);
    // the link counts what came in
    expect((await w.call(owner, "GET", `${base}/upload-links`)).json.data.uploadLinks[0]).toMatchObject({ uploads: 1, bytes: img.length });
  });

  it("type, size, count and total limits hold; concurrent guests can't pass them", async () => {
    const t = token((await create({ maxFiles: 3, maxFileBytes: 1000, maxTotalBytes: 2500, allowedTypes: ["image/*", "application/pdf"] })).json.data.url);
    expect((await send(t, "a.exe", randomBytes(10), "application/x-msdownload")).json.error.code).toBe("unsupported_type");
    expect((await send(t, "big.pdf", randomBytes(1001), "application/pdf")).status).toBe(413);
    const results = await Promise.all([1, 2, 3, 4, 5].map((i) => send(t, `p${i}.pdf`, randomBytes(900), "application/pdf")));
    const accepted = results.filter((r) => r.status === 201).length;
    expect(accepted).toBe(2); // 3 × 900 would pass the 2,500-byte total
    expect(results.filter((r) => r.status === 409).every((r) => r.json.error.code === "limit_reached")).toBe(true);
    expect((await send(t, "small.pdf", randomBytes(100), "application/pdf")).status).toBe(201); // the third file fits
    expect((await send(t, "more.pdf", randomBytes(10), "application/pdf")).json.error.code).toBe("limit_reached"); // count reached
    const row = w.db.prepare(`SELECT uploads, bytes FROM media_upload_links`).get() as { uploads: number; bytes: number };
    expect(row).toEqual({ uploads: 3, bytes: 1900 });
    expect((await open(t)).json.data.remaining).toEqual({ files: 0, bytes: 600 });
  });

  it("same names get a number; review can be turned off (files still private, never public)", async () => {
    const t = token((await create({ requiresReview: false })).json.data.url);
    await send(t, "notes.txt", randomBytes(20), "text/plain");
    const second = await send(t, "notes.txt", randomBytes(21), "text/plain");
    expect(second.json.data.file.name).toBe("notes (2).txt");
    await w.runPipelines();
    const live = await files("?folder=%2Fincoming");
    expect(live.map((f: { name: string; status: string }) => `${f.name}:${f.status}`).sort()).toEqual(["notes (2).txt:private", "notes.txt:private"]);
  });

  it("expired and revoked links stop at the next request; only managers manage links; inputs are bounded; sharing off refuses", async () => {
    const r = await create({ expiresIn: 3600 });
    const t = token(r.json.data.url);
    w.now = new Date(w.now.getTime() + 3601_000);
    expect((await open(t)).status).toBe(410);
    expect((await send(t, "late.bin", randomBytes(5))).status).toBe(410);
    w.now = new Date();
    const r2 = await create({});
    const t2 = token(r2.json.data.url);
    expect((await send(t2, "ok.bin", randomBytes(5))).status).toBe(201);
    await w.call(owner, "DELETE", `${base}/upload-links/${r2.json.data.uploadLink.id}`);
    expect((await open(t2)).status).toBe(404);
    expect((await send(t2, "after.bin", randomBytes(5))).status).toBe(404);

    expect((await create({}, editor)).status).toBe(404); // upload_link.manage is managers'
    expect((await w.call(editor, "GET", `${base}/upload-links`)).status).toBe(404);
    expect((await create({ folder: "/missing" })).status).toBe(404);
    for (const bad of [{ maxFiles: 0 }, { maxFileBytes: 60 * 1024 * 1024 }, { allowedTypes: ["not a type"] }, { expiresIn: 5 }, { folder: "/a/../b" }]) {
      expect([JSON.stringify(bad), (await create(bad)).status]).toEqual([JSON.stringify(bad), 422]);
    }
    expect((await send(t2.replace(/.$/, "x"), "x.bin", randomBytes(5))).status).toBe(404);
    w.env.PUBLIC_SHARING = "off";
    expect((await create({})).status).toBe(409);
    expect((await open(token((await (async () => { w.env.PUBLIC_SHARING = "on"; return create({}); })()).json.data.url))).status).toBe(200);
  });

  it("a guest's file can't replace a member's, and a suspended team takes nothing", async () => {
    const t = token((await create({ requiresReview: false })).json.data.url);
    await send(t, "keep.bin", randomBytes(10));
    const before = (await files("?folder=%2Fincoming"))[0];
    await send(t, "keep.bin", randomBytes(11));
    const after = await files("?folder=%2Fincoming");
    expect(after.find((f: { id: string }) => f.id === before.id).version).toBe(1); // untouched
    w.db.prepare(`INSERT INTO media_org_status (org_id, suspended_at, reason, decided_by) VALUES (?, ?, 'test', 'op')`).run(A.id, new Date().toISOString());
    expect((await send(t, "x.bin", randomBytes(5))).status).toBe(451);
  });
});
